package dev.pocketengine.features.memory;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.HashSet;
import java.util.Set;
import org.json.JSONArray;
import org.json.JSONObject;

/** Portable data only. These closed objects are never grants, SourceRef currentness, executable
 * review/candidate state, model context or a replacement source/forget registry. */
public final class MemoryArchive {
    public static final String FORMAT="pocketworld.owner-memory-archive.v1";
    public static final String IMPORT_FORMAT="pocketworld.owner-memory-archive-import.v1";
    public static final int MAX_BYTES=8_000_000,MAX_IMPORTS=32;
    private static final Set<String> TOP=Set.of("format","version","ownerId","spaceId","records","sources","recordForgetBarriers","learningCandidates","candidateHistory","priorImports","counts","sectionDigest","executionAuthorized","activeAuthorityIncluded");
    static final Set<String> RECORD=Set.of("id","ownerId","spaceId","layer","text","source","confidence","sourceIds","sourceRefs","core","revision","expiresAt","createdAt","updatedAt","formation","learningCandidateId","validationStatus","applicability","parentRevisions","supersedes","supersededAt","archiveOnly","importedFrom","archiveEvidence","appKnowledge","assertion","assertionCorrectionAt","assertionResolution");
    static final Set<String> CANDIDATE=Set.of("id","ownerId","spaceId","layer","text","reason","applicability","confidence","sourceRefs","status","revision","dedupKey","contentKey","validationStatus","createdAt","updatedAt","recordRefs","expiresAt","formation","acceptedFromRevision","acceptedRecordId","rejectionReason","rejectedFromRevision","previousStatus","invalidationReason","suppressedKeys","appKnowledge","assertion");
    static final Set<String> HISTORY=Set.of("id","ownerId","spaceId","status","outcome","sourceRefs","dedupKey","contentKey","revision","archivedAt","acceptedRecordId","recordRefs","expiresAt","formation");
    private MemoryArchive(){}
    public static MemoryBook.Scope ownerScope(JSONObject scope){MemoryBook.Scope s=MemoryBook.Scope.from(scope);if(!"owner".equals(s.ownerId)||!"private".equals(s.spaceId))throw new SecurityException("档案只读取本机主人明确选择的私人记忆范围");return s;}
    static void keys(JSONObject value,Set<String> allowed){for(var it=value.keys();it.hasNext();)if(!allowed.contains(it.next()))throw new SecurityException("记忆档案含未知字段；未恢复或执行");}
    static void scoped(JSONObject row,MemoryBook.Scope scope){if(!scope.matches(row))throw new SecurityException("记忆档案包含其它主体或群空间");}
    static void id(JSONObject row){String id=row.optString("id");if(!id.matches("[0-9a-f-]{36}"))throw new IllegalArgumentException("档案原记录身份无效");SourceRef.integer(row,"revision",1);}
    static void refs(JSONArray refs,MemoryBook.Scope scope)throws Exception{if(refs==null||refs.length()>1000)throw new IllegalArgumentException("档案来源数量无效");for(int i=0;i<refs.length();i++){JSONObject row=refs.optJSONObject(i);if(row==null)throw new IllegalArgumentException("档案来源不是准确引用");SourceRef ref=SourceRef.fromJson(row);if(!scope.acceptsSource(ref)||row.length()!=ref.toJson().length())throw new SecurityException("档案来源不能扩主体或包含授权字段");}}
    static void record(JSONObject row,MemoryBook.Scope scope)throws Exception{
        keys(row,RECORD);MemoryAssertion.checkStored(row,9);scoped(row,scope);id(row);text(row,"text",1,4000);text(row,"source",1,500);if(!Set.of("fact","preference","episodic","procedural").contains(row.getString("layer")))throw new IllegalArgumentException("档案记忆层级无效");
        if(!(row.opt("core")instanceof Boolean))throw new IllegalArgumentException("档案核心标记无效");double c=row.getDouble("confidence");if(!Double.isFinite(c)||c<0||c>1)throw new IllegalArgumentException("档案可信度无效");refs(row.getJSONArray("sourceRefs"),scope);if(row.getJSONArray("sourceIds").length()>1000)throw new IllegalArgumentException("档案父记忆数量超限");
        if(row.has("archiveOnly")||row.has("importedFrom"))checkRestoredRecord(row);
    }
    static void candidate(JSONObject row,MemoryBook.Scope scope)throws Exception{keys(row,CANDIDATE);MemoryAssertion.checkStored(row,9);scoped(row,scope);id(row);refs(row.getJSONArray("sourceRefs"),scope);if(!Set.of("pending","accepted","rejected","invalidated").contains(row.getString("status")))throw new IllegalArgumentException("档案候选状态无效");if("invalidated".equals(row.getString("status"))){if(row.has("text"))throw new SecurityException("失效候选不能携带已退休正文");}else{text(row,"text",1,4000);if(!Set.of("fact","preference","episodic","procedural").contains(row.getString("layer")))throw new IllegalArgumentException("档案候选层级无效");double confidence=row.getDouble("confidence");if(!Double.isFinite(confidence)||confidence<0||confidence>1)throw new IllegalArgumentException("档案候选可信度无效");}}
    private static void sourceState(JSONObject row,MemoryBook.Scope scope)throws Exception{SourceRef ref=SourceRef.fromJson(row);Set<String> allowed=new HashSet<>(Set.of("kind","sourceId","revision","ownerId","spaceId","deleted","forgottenThrough"));if(ref.workspace!=null)allowed.add("workspace");keys(row,allowed);if(row.length()!=allowed.size()||!ref.belongsTo(scope)||!(row.opt("deleted")instanceof Boolean)||SourceRef.integer(row,"forgottenThrough",0)>ref.revision)throw new SecurityException("档案来源屏障无效");}
    static void recordFence(JSONObject row,MemoryBook.Scope scope)throws Exception{keys(row,Set.of("ownerId","spaceId","recordId","forgottenThrough"));scoped(row,scope);if(row.length()!=4||row.optString("recordId").isEmpty()||SourceRef.integer(row,"forgottenThrough",1)<1)throw new IllegalArgumentException("档案原记忆墓碑无效");}
    static void history(JSONObject row,MemoryBook.Scope scope)throws Exception{keys(row,HISTORY);scoped(row,scope);id(row);refs(row.getJSONArray("sourceRefs"),scope);}
    private static void text(JSONObject row,String key,int min,int max)throws Exception{Object value=row.get(key);if(!(value instanceof String)||((String)value).length()<min||((String)value).length()>max)throw new IllegalArgumentException("档案文字超出支持范围");MemoryBook.validateUnicode((String)value);}
    public static JSONObject counts(JSONObject value)throws Exception{
        JSONArray records=value.getJSONArray("records"),candidates=value.getJSONArray("learningCandidates");int pending=0,slots=records.length(),deleted=0;
        for(int i=0;i<candidates.length();i++){JSONObject row=candidates.getJSONObject(i);if("pending".equals(row.optString("status")))pending++;if(row.has("text"))slots++;}
        JSONArray sources=value.getJSONArray("sources");for(int i=0;i<sources.length();i++)if(sources.getJSONObject(i).optBoolean("deleted"))deleted++;
        return new JSONObject().put("records",records.length()).put("sources",sources.length()).put("sourceTombstones",deleted).put("recordTombstones",value.getJSONArray("recordForgetBarriers").length()).put("learningCandidates",candidates.length()).put("pendingCandidates",pending).put("candidateHistory",value.getJSONArray("candidateHistory").length()).put("restoreRecordSlots",slots);
    }
    /** Check size before copying/canonical serialization. Limits are local data bounds, not scope. */
    static void bounded(Object value){long[] budget={MAX_BYTES,200000};walk(value,budget,0);}
    private static void walk(Object value,long[] budget,int depth){if(depth>32||--budget[1]<0)throw new IllegalArgumentException("档案嵌套或节点数超出支持范围");budget[0]-=2;
        if(value instanceof JSONObject){JSONObject object=(JSONObject)value;if(object.length()>64)throw new IllegalArgumentException("档案字段过多");for(var i=object.keys();i.hasNext();){String key=i.next();walk(key,budget,depth+1);walk(object.opt(key),budget,depth+1);}}
        else if(value instanceof JSONArray){JSONArray a=(JSONArray)value;if(a.length()>10000)throw new IllegalArgumentException("档案数组过长");for(int i=0;i<a.length();i++)walk(a.opt(i),budget,depth+1);}
        else if(value instanceof String){String s=(String)value;MemoryBook.validateUnicode(s);if(s.length()>100000)throw new IllegalArgumentException("档案单项文字过长");budget[0]-=s.getBytes(StandardCharsets.UTF_8).length+2L;}
        else if(value==JSONObject.NULL||value==null||value instanceof Boolean||value instanceof Number){if(value instanceof Double&&!Double.isFinite((Double)value)||value instanceof Float&&!Float.isFinite((Float)value))throw new IllegalArgumentException("档案数值无效");budget[0]-=32;}
        else throw new IllegalArgumentException("档案含非JSON类型");if(budget[0]<0)throw new IllegalArgumentException("记忆档案超过8MB；未部分覆盖原Book");
    }
    public static JSONObject checked(JSONObject raw,JSONObject authenticatedScope)throws Exception{
        MemoryBook.Scope scope=ownerScope(authenticatedScope);if(raw==null)throw new IllegalArgumentException("缺少记忆档案");bounded(raw);raw=new JSONObject(raw.toString());bounded(raw);keys(raw,TOP);if(raw.length()!=TOP.size()||!FORMAT.equals(raw.optString("format"))||SourceRef.integer(raw,"version",1)!=1||!Boolean.FALSE.equals(raw.opt("executionAuthorized"))||!Boolean.FALSE.equals(raw.opt("activeAuthorityIncluded")))throw new SecurityException("档案格式或权限边界无效");scoped(raw,scope);
        JSONArray records=raw.getJSONArray("records"),sources=raw.getJSONArray("sources"),candidates=raw.getJSONArray("learningCandidates"),fences=raw.getJSONArray("recordForgetBarriers"),history=raw.getJSONArray("candidateHistory"),prior=raw.getJSONArray("priorImports");
        if(records.length()>1000||sources.length()>10000||candidates.length()>200||fences.length()>10000||history.length()>1000||prior.length()>MAX_IMPORTS)throw new IllegalArgumentException("档案数量超出本机原Book支持范围");Set<String> ids=new HashSet<>();
        for(int i=0;i<records.length();i++){JSONObject row=records.getJSONObject(i);record(row,scope);if(!ids.add(row.getString("id")))throw new IllegalArgumentException("档案原记忆身份重复");}
        ids.clear();for(int i=0;i<candidates.length();i++){JSONObject row=candidates.getJSONObject(i);candidate(row,scope);if(!ids.add(row.getString("id")))throw new IllegalArgumentException("档案候选身份重复");}
        for(int i=0;i<sources.length();i++)sourceState(sources.getJSONObject(i),scope);
        for(int i=0;i<fences.length();i++)recordFence(fences.getJSONObject(i),scope);
        for(int i=0;i<history.length();i++)history(history.getJSONObject(i),scope);
        for(int i=0;i<prior.length();i++){if(!IMPORT_FORMAT.equals(prior.getJSONObject(i).optString("format")))throw new SecurityException("私人档案不混入项目namespace沿革");checkImportMetadata(prior.getJSONObject(i),0);}
        java.util.List<JSONObject> receipts=new java.util.ArrayList<>();for(int i=0;i<prior.length();i++)receipts.add(prior.getJSONObject(i));Set<String> lineages=lineageKeys(receipts);for(int i=0;i<records.length();i++)checkLineage(records.getJSONObject(i),lineages,0);
        if(!canonical(counts(raw)).equals(canonical(raw.getJSONObject("counts"))))throw new SecurityException("档案计数与实际范围不一致");String expected=raw.getString("sectionDigest");if(!expected.matches("[0-9a-f]{64}")||!expected.equals(sectionDigest(raw)))throw new SecurityException("档案分段hash不匹配，未恢复替代内容");return new JSONObject(raw.toString());
    }
    public static String sectionDigest(JSONObject section)throws Exception{JSONObject data=new JSONObject(section.toString());data.remove("sectionDigest");byte[] hash=MessageDigest.getInstance("SHA-256").digest(canonical(data).getBytes(StandardCharsets.UTF_8));StringBuilder out=new StringBuilder();for(byte b:hash)out.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return out.toString();}
    static String canonical(Object value)throws Exception{if(value instanceof JSONObject){JSONObject o=(JSONObject)value;java.util.List<String> k=new java.util.ArrayList<>();o.keys().forEachRemaining(k::add);java.util.Collections.sort(k);StringBuilder s=new StringBuilder("{");for(String x:k){if(s.length()>1)s.append(',');s.append(JSONObject.quote(x)).append(':').append(canonical(o.get(x)));}return s.append('}').toString();}if(value instanceof JSONArray){JSONArray a=(JSONArray)value;StringBuilder s=new StringBuilder("[");for(int i=0;i<a.length();i++){if(i>0)s.append(',');s.append(canonical(a.get(i)));}return s.append(']').toString();}return value==JSONObject.NULL?"null":value instanceof String?JSONObject.quote((String)value):String.valueOf(value);}
    static void checkRestoredRecord(JSONObject row)throws Exception{
        if(row.optString("spaceId").startsWith("project:")){ProjectMemoryArchive.checkRestoredRecord(row);return;}
        if(!Boolean.TRUE.equals(row.opt("archiveOnly"))||row.optBoolean("core")||!"archive_restore".equals(row.optString("formation"))||row.getJSONArray("sourceRefs").length()!=0||row.getJSONArray("sourceIds").length()!=0)throw new SecurityException("档案恢复记录不能带活动来源或核心权限");JSONObject from=row.getJSONObject("importedFrom");keys(from,Set.of("archiveImportId","originalId","sectionDigest","originalType"));if(from.length()!=4||!from.optString("archiveImportId").matches("[A-Za-z0-9:_-]{1,160}")||!from.optString("originalId").matches("[0-9a-f-]{36}")||!from.optString("sectionDigest").matches("[0-9a-f]{64}")||!Set.of("record","candidate").contains(from.optString("originalType")))throw new SecurityException("档案恢复来源定位无效");JSONObject evidence=row.getJSONObject("archiveEvidence");keys(evidence,Set.of("originalType","original"));if(evidence.length()!=2||!from.getString("originalType").equals(evidence.getString("originalType"))||evidence.getJSONObject("original").has("text")||!from.getString("originalId").equals(evidence.getJSONObject("original").getString("id")))throw new SecurityException("档案原文只能在本条保留一次，不把旧状态变为执行权限");JSONObject original=evidence.getJSONObject("original");keys(original,from.getString("originalType").equals("record")?RECORD:CANDIDATE);MemoryBook.Scope scope=ownerScope(row);scoped(original,scope);refs(original.getJSONArray("sourceRefs"),scope);bounded(evidence);
    }
    /** Matching closed native receipt/mapping facts only, not an ancestry claim or read grant. */
    static Set<String> lineageKeys(Iterable<JSONObject> checkedReceipts)throws Exception{Set<String> result=new HashSet<>();for(JSONObject receipt:checkedReceipts)collectLineageKeys(receipt,result,0);return result;}
    private static String lineageKey(String owner,String space,String imported,String digest,String id,String original,String type,String originSpace){return new JSONArray().put(owner).put(space).put(imported).put(digest).put(id).put(original).put(type).put(originSpace).toString();}
    private static void collectLineageKeys(JSONObject receipt,Set<String> keys,int depth)throws Exception{
        if(depth>8||!Set.of(IMPORT_FORMAT,ProjectMemoryArchive.IMPORT_FORMAT).contains(receipt.optString("format")))throw new SecurityException("档案沿革不是原native导入回执");JSONArray mappings=receipt.getJSONArray("mappings");for(int i=0;i<mappings.length();i++){JSONObject m=mappings.getJSONObject(i);keys.add(lineageKey(receipt.getString("ownerId"),receipt.getString("spaceId"),receipt.getString("archiveImportId"),receipt.getString("sectionDigest"),m.getString("newId"),m.getString("originalId"),m.getString("originalType"),ProjectMemoryArchive.IMPORT_FORMAT.equals(receipt.optString("format"))?receipt.getString("originalSpaceId"):receipt.getString("spaceId")));}JSONArray prior=receipt.getJSONArray("priorImports");for(int i=0;i<prior.length();i++)collectLineageKeys(prior.getJSONObject(i),keys,depth+1);
    }
    static void checkLineage(JSONObject row,Set<String> checkedLineages,int depth)throws Exception{
        if(!row.has("archiveOnly")&&!row.has("importedFrom"))return;if(depth>32)throw new SecurityException("档案原沿革超过已验证范围");checkRestoredRecord(row);JSONObject from=row.getJSONObject("importedFrom");String key=lineageKey(row.getString("ownerId"),row.getString("spaceId"),from.getString("archiveImportId"),from.getString("sectionDigest"),row.getString("id"),from.getString("originalId"),from.getString("originalType"),row.getJSONObject("archiveEvidence").getJSONObject("original").getString("spaceId"));if(!checkedLineages.contains(key))throw new SecurityException("档案原行缺少同importId/sectionDigest及确切新旧ID/type的native映射，未臆造祖先");checkLineage(row.getJSONObject("archiveEvidence").getJSONObject("original"),checkedLineages,depth+1);
    }
    static void checkImportMetadata(JSONObject value,int depth)throws Exception{
        if(ProjectMemoryArchive.IMPORT_FORMAT.equals(value.optString("format"))){ProjectMemoryArchive.checkImportMetadata(value,depth);return;}
        if(depth>8)throw new IllegalArgumentException("档案恢复沿革超过8层，需保留原ZIP只读核对");keys(value,Set.of("format","archiveImportId","sectionDigest","ownerId","spaceId","importedAt","mappings","sourceEvidence","recordForgetEvidence","candidateMetadata","candidateHistoryEvidence","priorImports","counts"));if(value.length()!=13||!IMPORT_FORMAT.equals(value.optString("format"))||!value.optString("archiveImportId").matches("[A-Za-z0-9:_-]{1,160}")||!value.optString("sectionDigest").matches("[0-9a-f]{64}")||!"owner".equals(value.optString("ownerId"))||!"private".equals(value.optString("spaceId")))throw new SecurityException("档案恢复回执身份无效");SourceRef.integer(value,"importedAt",0);JSONArray mappings=value.getJSONArray("mappings");if(mappings.length()>1200)throw new IllegalArgumentException("档案恢复映射超限");Set<String> seen=new HashSet<>(),originals=new HashSet<>();int recordMappings=0,candidateMappings=0;for(int i=0;i<mappings.length();i++){JSONObject m=mappings.getJSONObject(i);keys(m,Set.of("originalId","originalType","newId"));if(m.length()!=3||!m.optString("originalId").matches("[0-9a-f-]{36}")||!m.optString("newId").matches("[0-9a-f-]{36}")||!Set.of("record","candidate").contains(m.optString("originalType"))||!seen.add(m.getString("newId"))||!originals.add(m.getString("originalType")+":"+m.getString("originalId")))throw new SecurityException("档案恢复映射无效");if("record".equals(m.getString("originalType")))recordMappings++;else candidateMappings++;}
        MemoryBook.Scope scope=ownerScope(value);JSONArray sources=value.getJSONArray("sourceEvidence"),fences=value.getJSONArray("recordForgetEvidence"),candidates=value.getJSONArray("candidateMetadata"),history=value.getJSONArray("candidateHistoryEvidence");if(sources.length()>10000||fences.length()>10000||candidates.length()>200||history.length()>1000)throw new IllegalArgumentException("档案原证据数量超限");for(int i=0;i<sources.length();i++)sourceState(sources.getJSONObject(i),scope);for(int i=0;i<fences.length();i++)recordFence(fences.getJSONObject(i),scope);for(int i=0;i<candidates.length();i++){JSONObject row=candidates.getJSONObject(i);candidate(row,scope);if(row.has("text"))throw new SecurityException("档案回执不能另存候选正文副本");}for(int i=0;i<history.length();i++)history(history.getJSONObject(i),scope);
        JSONObject counts=value.getJSONObject("counts");Set<String> countKeys=Set.of("records","sources","sourceTombstones","recordTombstones","learningCandidates","pendingCandidates","candidateHistory","restoreRecordSlots");keys(counts,countKeys);if(counts.length()!=countKeys.size())throw new SecurityException("档案回执计数缺失");for(String key:countKeys)if(SourceRef.integer(counts,key,0)>10000)throw new IllegalArgumentException("档案回执计数超限");int deleted=0;for(int i=0;i<sources.length();i++)if(sources.getJSONObject(i).getBoolean("deleted"))deleted++;if(counts.getInt("records")!=recordMappings||counts.getInt("learningCandidates")!=candidateMappings+candidates.length()||counts.getInt("pendingCandidates")>candidateMappings||counts.getInt("sources")!=sources.length()||counts.getInt("sourceTombstones")!=deleted||counts.getInt("recordTombstones")!=fences.length()||counts.getInt("candidateHistory")!=history.length()||counts.getInt("restoreRecordSlots")!=mappings.length())throw new SecurityException("档案回执计数不符");
        JSONArray prior=value.getJSONArray("priorImports");if(prior.length()>MAX_IMPORTS)throw new IllegalArgumentException("档案恢复沿革超限");for(int i=0;i<prior.length();i++){if(!IMPORT_FORMAT.equals(prior.getJSONObject(i).optString("format")))throw new SecurityException("私人导入沿革格式未扩权为项目档案");checkImportMetadata(prior.getJSONObject(i),depth+1);}bounded(value);
    }
}
